import{_ as o,C as a,o as n,c as i,a2 as r,E as s}from"./chunks/framework.BSaF8iZ6.js";const b=JSON.parse('{"title":"Users & Roles","description":"","frontmatter":{},"headers":[],"relativePath":"seller-panel/users-and-roles.md","filePath":"seller-panel/users-and-roles.md","lastUpdated":1789411447000}'),l={name:"seller-panel/users-and-roles.md"};function d(h,e,m,g,c,u){const t=a("ImagePopup");return n(),i("div",null,[e[0]||(e[0]=r('<h1 id="users-roles" tabindex="-1">Users &amp; Roles <a class="header-anchor" href="#users-roles" aria-label="Permalink to &quot;Users &amp; Roles&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>A shop owner can add team members who sign in to the Seller Panel with their own email and password. A role decides what each team member can see and do.</p><p>Create a role first: a team member can&#39;t be added without one, and a new shop has no roles.</p><h2 id="create-a-role" tabindex="-1">Create a role <a class="header-anchor" href="#create-a-role" aria-label="Permalink to &quot;Create a role&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt;&gt; Roles</strong>.</li><li>Click <strong>Create Role</strong>.</li><li>In <strong>General</strong>, enter a <strong>Name</strong> and <strong>Description</strong>.</li><li>In <strong>Access Control</strong>, choose the <strong>Permissions</strong>: <ul><li><strong>All</strong> gives access to everything in the permission tree. Team members still can&#39;t open <strong>My Profile</strong> or <strong>Plans</strong>.</li><li><strong>Custom</strong> shows a permission tree. Tick what the role may use, or type in <strong>Search permissions</strong> to find an entry.</li></ul></li><li>Click <strong>Save Role</strong>.</li></ol>',6)),s(t,{src:"/images/users-and-roles/role-create.png",alt:"The Create Role page with the permission tree"}),s(t,{src:"/images/users-and-roles/settings-roles.png",alt:"The Roles list"}),e[1]||(e[1]=r('<h3 id="what-the-permission-tree-covers" tabindex="-1">What the permission tree covers <a class="header-anchor" href="#what-the-permission-tree-covers" aria-label="Permalink to &quot;What the permission tree covers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Includes</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td>The dashboard</td></tr><tr><td><strong>Manage Profile</strong></td><td>Nothing for team members, because only the shop owner can open <strong>My Profile</strong></td></tr><tr><td><strong>Catalog</strong></td><td>List Your Product; Products, with Assign, Edit, Delete, Product Barcode (Generate and Print) and Generate Content With Magic AI; Bulk Upload, with Imports (Create, Edit, Delete and Import)</td></tr><tr><td><strong>Inventories</strong></td><td>Manage Inventory, with Update Status and Save Inventories; Inventory Sources, with Create, Edit and Delete</td></tr><tr><td><strong>Pricing</strong></td><td>Manage Pricing, with Save Prices</td></tr><tr><td><strong>Marketing</strong></td><td>Product Discounts, with Create, Edit, Delete and Join (View, Enroll and Withdraw) for the store&#39;s discounts; Checkout Deals, with Create, Edit, Copy, Delete and Coupons</td></tr><tr><td><strong>Sales</strong></td><td>Orders, with View, Cancel, Invoice, Print Invoice, Shipment and Payment Request; RMA, with View; Bookings; Transactions, with View and Print</td></tr><tr><td><strong>Performance</strong></td><td>Account Health, with Refresh Account Health; Seller Reviews; Product Reviews</td></tr><tr><td><strong>Reporting</strong></td><td>Sales, Customers, Products</td></tr><tr><td><strong>Communication</strong></td><td>Admin, Customers</td></tr><tr><td><strong>Customers</strong></td><td>The customers list</td></tr><tr><td><strong>Settings</strong></td><td>General; Users, with Create, Edit and Delete; Roles, with Create, Edit and Delete</td></tr></tbody></table><p>A <strong>Custom</strong> role needs at least one permission.</p><p>A role that a team member uses can&#39;t be deleted, and neither can your only role.</p><h2 id="add-a-team-member" tabindex="-1">Add a team member <a class="header-anchor" href="#add-a-team-member" aria-label="Permalink to &quot;Add a team member&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt;&gt; Users</strong>.</li><li>Click <strong>Create User</strong>.</li><li>Enter the <strong>Name</strong>, <strong>Email</strong> and <strong>Phone Number</strong>.</li><li>Enter a <strong>Password</strong> of at least 6 characters, and enter it again in <strong>Confirm Password</strong>.</li><li>Choose a <strong>Role</strong>.</li><li>Leave <strong>Status</strong> switched on so the account is active.</li><li>Click <strong>Save User</strong>.</li></ol>',6)),s(t,{src:"/images/users-and-roles/settings-users.png",alt:"The Users list"}),e[2]||(e[2]=r('<p>No invitation email is sent. Give the team member their email and password, and ask them to sign in on <strong>Seller Login</strong>. The email and phone number must not be used by any other seller or team member on the marketplace.</p><h2 id="what-team-members-can-do" tabindex="-1">What team members can do <a class="header-anchor" href="#what-team-members-can-do" aria-label="Permalink to &quot;What team members can do&quot;">​</a></h2><ul><li>They see only the menus their role allows. If their role includes <strong>Dashboard</strong>, they land on the dashboard. Otherwise they land on the first page they are allowed to open.</li><li>They work with your shop&#39;s products, orders and customers.</li><li>They can&#39;t open <strong>My Profile</strong>. Shop details are for the owner only.</li><li>They can change their own password and language under <strong>Settings &gt;&gt; General</strong>, if their role allows it. See <a href="./account-settings">Account Settings</a>.</li></ul><h2 id="suspend-or-remove-a-team-member" tabindex="-1">Suspend or remove a team member <a class="header-anchor" href="#suspend-or-remove-a-team-member" aria-label="Permalink to &quot;Suspend or remove a team member&quot;">​</a></h2><ul><li>To suspend, click the edit icon on their row, switch <strong>Status</strong> off and click <strong>Save User</strong>. They are signed out and can&#39;t sign in until you switch it back on. When you edit a team member, leave the password fields empty to keep their current password.</li><li>To remove, click the delete icon on their row.</li></ul><h2 id="subscription-plans-and-team-size" tabindex="-1">Subscription plans and team size <a class="header-anchor" href="#subscription-plans-and-team-size" aria-label="Permalink to &quot;Subscription plans and team size&quot;">​</a></h2><p>If the store uses subscription plans:</p><ul><li>Your plan&#39;s <strong>Max Staff</strong> limits how many team members you can add. Once you reach it, you&#39;ll see <strong>You have reached max limit of … Users.</strong></li><li>A team member can only use what both their role and your plan allow.</li></ul><p>See <a href="./../subscriptions/choosing-a-plan">Choosing a Plan</a>.</p>',9))])}const w=o(l,[["render",d]]);export{b as __pageData,w as default};
